//! Shared fixtures for the no-store daily play path.

use crate::test_support::mint_test_token;
use axum::body::Body;
use axum::http::{Method, Request};

/// Today's served puzzle for a game, as SubmitGuess grades it (no database:
/// generated by the daily pipeline for the product day).
pub(super) async fn served_today(game_slug: &str) -> (serde_json::Value, serde_json::Value) {
    use puzzled_core::puzzle_play::daily_time::product_day_key;
    let today = product_day_key(chrono::Utc::now());
    match crate::capabilities::daily_pipeline::resolve(None, game_slug, today, None).await {
        Ok(resolved) => (resolved.puzzle_data, resolved.solution),
        Err(error) => panic!("resolve {game_slug}: {error}"),
    }
}

pub(super) fn player_submit(body: String) -> Request<Body> {
    match Request::builder()
        .method(Method::POST)
        .uri("/puzzled.v1.PuzzleService/SubmitGuess")
        .header(axum::http::header::CONTENT_TYPE, "application/json")
        .header(
            "authorization",
            format!("Bearer {}", mint_test_token("user_test_01")),
        )
        .body(Body::from(body))
    {
        Ok(r) => r,
        Err(error) => panic!("build: {error}"),
    }
}
